report.findings:
{% for slug, summary in (scan_summary_map or {}).items() %}
{% if summary.findings and summary.findings.grouped %}

  {% for group in summary.findings.grouped %}

    {% for finding in group.table_items %}

      {{ finding.title|default('') }}
      {{ finding.project_name|default('') }}
      {{ finding.target|default('') }}
      {{ group.slug }}
      {{ finding.cvss_score|default('') }}
      {{ finding.cvss_severity|default('') }}
      {{ finding.status|default('') }}
      {{ finding.scanner|default('') }}
      {{ finding.risk|default(finding.severity_label|default('')) }}
      {{ finding.description|default('') }}
      {{ finding.solution|default('') }}
      {{ finding.reference|default('') }}
      {% if finding.mitre_has_data %}

        {% for t in finding.mitre_techniques %}

          {{ t.id }}
          {{ t.name }}
          {{ t.tactic }}

        {% endfor %}

      {% endif %}
      {% if finding.identifier %}
      {{ finding.identifier }}
      {% endif %}
      {% if finding.detected %}
      {{ finding.detected.strftime('%Y-%m-%d %H:%M') }}
      {% endif %}

    {% endfor %}

  {% endfor %}

{% endif %}
{% endfor %}
